async (state, model) => {
  const query = state.customerQuery || state.messages[state.messages.length - 1]?.content || '';
  const prompt = `Analyze this customer query and identify the key issue: ${query}`;

  const result = await model.invoke([{ role: 'user', content: prompt }]);

  return {
    customerQuery: query,
    messages: [{ role: 'assistant', content: `Query Analysis: ${result.content}` }]
  };
}

async (state, model) => {
  const prompt = `Use the product_knowledge skill to find relevant information for: ${state.customerQuery}`;

  const result = await model.invoke([{ role: 'user', content: prompt }]);

  return {
    productInfo: { retrieved: true, data: result.content.toString() },
    messages: [{ role: 'assistant', content: `Knowledge Retrieved: ${result.content}` }]
  };
}

async (state, model) => {
  const context = `Customer Query: ${state.customerQuery}\nProduct Info: ${JSON.stringify(state.productInfo)}`;
  const prompt = `Use the troubleshooting skill to provide a solution for:\n${context}`;

  const result = await model.invoke([{ role: 'user', content: prompt }]);

  return {
    troubleshootingSteps: [result.content.toString()],
    resolution: result.content.toString(),
    messages: [{ role: 'assistant', content: `Solution Provided: ${result.content}` }]
  };
}

async (state, model) => {
  const prompt = `Summarize the support interaction and ask for feedback:\nQuery: ${state.customerQuery}\nResolution: ${state.resolution}`;

  const result = await model.invoke([{ role: 'user', content: prompt }]);

  return {
    customerSatisfaction: 'verified',
    messages: [{ role: 'assistant', content: `Follow-up: ${result.content}` }]
  };
}
